import z3, time, sys

def bv32(x): return z3.BitVecVal(x,32)
def bv8(x): return z3.BitVecVal(x,8)

def expand(s):
    return s ^ (s << 16) ^ (s * z3.BitVecVal(12345,32))

def G(a,b,c):
    return z3.RotateLeft(a+b+c, 2)

def F(x):
    x0=z3.Extract(7,0,x); x1=z3.Extract(15,8,x); x2=z3.Extract(23,16,x); x3=z3.Extract(31,24,x)
    y2=G(x3^x2, x1^x0, bv8(1))
    y3=G(x3, y2, bv8(0))
    y1=G(x1^x0, y2, bv8(0))
    y0=G(x0, y1, bv8(1))
    return z3.Concat(y3,y2,y1,y0)

def encrypt(p, keys):
    left=z3.Extract(63,32,p); right=z3.Extract(31,0,p)
    right = right ^ left
    for r in range(4):
        mixed=F(right ^ keys[r])
        temp=right
        right=left ^ mixed
        left=temp
    left = left ^ right
    return z3.Concat(right,left)

pairs=[]
for line in open('/app/pairs.txt'):
    a,b=line.split()
    pairs.append((int(a),int(b)))

N=int(sys.argv[1]) if len(sys.argv)>1 else 3
seeds=[z3.BitVec(f'k{i}',20) for i in range(4)]
keys=[expand(z3.ZeroExt(12,s)) for s in seeds]
s=z3.Solver()
for i in range(N):
    p,c=pairs[i]
    s.add(encrypt(z3.BitVecVal(p,64),keys)==z3.BitVecVal(c,64))
print("solving",N,flush=True)
t=time.time()
print(s.check(), time.time()-t, flush=True)
if s.check()==z3.sat:
    m=s.model()
    vals=[m.eval(sd) for sd in seeds]
    print(vals)
